-- Speglar det som lades på databasen 2026-09-15 via apply_migration i tre delar:
--   cp96_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar, värdelista)
--   cp96_order_code_from_catalogue_part_02  (regler 1–20)
--   cp96_order_code_from_catalogue_part_03  (regler 21–41, dokumentkarta, produktspecar)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts cp96):
--   regler  41   md5 a875dfb6e92224b115617d6bbd4547d6   villkor 197f5557958136fdc9d4a87693db5547
--   värden  49   md5 5b079d5ad155ed564103796ebb80b0b6
--   schema       md5 54a9f1cb053d9717d8381d87875323df
-- Verifierat live: /sv/configurator/cp96 bygger CP96SDB32-100CJW-M9BWS (nyckelns exempel,
-- sida 129) och kräver dämpningskoden C för ø32–100.
--
-- CP96: beställnyckeln enligt SMC ISO Cylinder CP96 Series (ISO 15552).
-- GENERERAD ur src/lib/catalog/cp96.ts -- redigera inte för hand.
--
-- Rättar familjen cp96, som hade mallen 'CP96-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'.
-- SMC:s kod är CP96S{magnet}{fäste}{ø}-{slag}{dämpning}{bälg}{stång}-{givare}{kabel}{antal}-{special},
-- t.ex. CP96SDB32-100CJW-M9BWS (sida 129). Fäste, bälg och dubbel kolvstång
-- fanns inte alls; dämpningskoden C hör till ø32–100 och saknas för ø125.
--
-- SMC-CP96 får katalogens slag, temperatur och portar.

begin;

create schema if not exists backup;
create table if not exists backup.cp96_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cp96'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cp96'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'cp96';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-CP96-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"32","label":"ø32 mm"},{"v":"40","label":"ø40 mm"},{"v":"50","label":"ø50 mm"},{"v":"63","label":"ø63 mm"},{"v":"80","label":"ø80 mm"},{"v":"100","label":"ø100 mm"},{"v":"125","label":"ø125 mm"}]},{"id":"mounting","step":2,"title_sv":"Fäste","title_en":"Mounting","required":true,"type":"single_select","options":[{"v":"B","label":"Basutförande"},{"v":"L","label":"Axiellt fotfäste"},{"v":"F","label":"Fläns vid kolvstången"},{"v":"G","label":"Fläns vid gaveln"},{"v":"C","label":"Enkelt gaffelfäste"},{"v":"D","label":"Dubbelt gaffelfäste (med gaffelsprint)"},{"v":"V","label":"Ställbart tappfäste"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":1,"max":2000,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (CP96SD)"}]},{"id":"cushion","step":5,"title_sv":"Dämpning","title_en":"Cushion","required":false,"type":"single_select","options":[{"v":"C","label":"Luftdämpning i båda ändar plus gummidämpning (ø32–100)"}]},{"id":"boot","step":6,"title_sv":"Kolvstångsbälg","title_en":"Rod boot","required":false,"type":"single_select","options":[{"v":"J","label":"Bälg i nylonduk, en ände"},{"v":"JJ","label":"Bälg i nylonduk, båda ändar (dubbel kolvstång)"},{"v":"K","label":"Värmebeständig bälg, en ände"},{"v":"KK","label":"Värmebeständig bälg, båda ändar (dubbel kolvstång)"}]},{"id":"rod","step":7,"title_sv":"Kolvstång","title_en":"Rod","required":false,"type":"single_select","options":[{"v":"W","label":"Dubbel kolvstång (genomgående; slag ≤ 1000)"}]},{"id":"switch","step":8,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN"},{"v":"M9P","label":"D-M9P, 3-tråd PNP"},{"v":"M9B","label":"D-M9B, 2-tråd"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät"},{"v":"A96","label":"D-A96, reed 3-tråd"},{"v":"A93","label":"D-A93, reed 2-tråd"},{"v":"A90","label":"D-A90, reed utan indikering"}]},{"id":"lead","step":9,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":10,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre givare"}]},{"id":"mto","step":11,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XA","label":"-XA□ Ändrad kolvstångsände (XA0–30, mått anges vid beställning)"},{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (utan magnet och givare; 50–500 mm/s)"},{"v":"XC4","label":"-XC4 Kraftig avstrykare (ø32–100)"},{"v":"XC7","label":"-XC7 Dragstänger, muttrar m.m. i rostfritt"},{"v":"XC22","label":"-XC22 Fluorgummitätningar"},{"v":"XC35","label":"-XC35 Spiralavstrykare (ø32–100)"},{"v":"XC65","label":"-XC65 Rostfritt (XC7 + XC68; slag ≤ 1800/1700/1600)"},{"v":"XC68","label":"-XC68 Rostfri hårdkromad kolvstång och stångmutter (slag ≤ 1800/1700/1600)"},{"v":"XC85","label":"-XC85 Fett för livsmedelsindustrin, NSF-H1 (ø32–100)"},{"v":"XC88","label":"-XC88 Svetssprutskydd: spiralavstrykare, smörjhållare, svetsfett, rostfri stång (ø32–100)"},{"v":"XC89","label":"-XC89 Svetssprutskydd: spiralavstrykare, smörjhållare, svetsfett, stång S45C (ø32–100)"}]}]}'::jsonb,
        'SMC CP96 ISO 15552-cylinder', 'SMC CP96 ISO 15552 cylinder', 'cylinder')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'ISO 15552-cylinder ø32–125, dubbelverkande enkel/dubbel kolvstång',
  description = 'SMC CP96 ISO 15552 profile cylinder, double acting single or double rod, ø32–125 mm, air cushion (plus bumper on ø32–100), strokes up to 2000 mm.',
  stroke_min_mm = 1,
  stroke_max_mm = 2000,
  order_code_template = 'CP96S{magnet}{mounting}{bore}-{stroke_mm}{cushion}{boot}{rod}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-CP96-V1'
where slug = 'cp96';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'cp96';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'cp96';

