delete from config_rules where schema_id = 'SCHEMA-CP96-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-CP96-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["32","40","50","63","80","100"]]},{">":[{"var":"stroke_mm"},0]},{"==":[{"var":"cushion"},""]}]},"message_sv":"ø32, 40, 50, 63, 80 och 100 har luftdämpning i båda ändar plus gummidämpning och skrivs med C — välj dämpningen (sida 129).","message_en":"ø32, 40, 50, 63, 80 and 100 has air cushion on both ends plus bumper cushion and is written with C — select the cushion (page 129).","goto_step":"cp96-cushion"},{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["125"]]},{"==":[{"var":"cushion"},"C"]}]},"message_sv":"ø125 har bara luftdämpning och skrivs utan bokstav — ta bort C (sida 129).","message_en":"ø125 has air cushion only and is written without a letter — remove C (page 129).","goto_step":"cp96-cushion"},{"severity":"error","if_json":{"and":[{"in":[{"var":"boot"},["JJ","KK"]]},{"!=":[{"var":"rod"},"W"]}]},"message_sv":"Bälg på båda ändar (JJ och KK) förutsätter dubbel kolvstång W — enkel kolvstång har bara en ände (sida 129).","message_en":"Rod boots on both ends (JJ and KK) need the double rod W — a single rod has only one end (page 129).","goto_step":"cp96-boot"},{"severity":"error","if_json":{"and":[{"==":[{"var":"rod"},"W"]},{">":[{"var":"stroke_mm"},1000]}]},"message_sv":"Dubbel kolvstång tillverkas upp till 1000 mm slag (sida 154).","message_en":"The double rod is manufactured up to 1000 mm stroke (page 154).","goto_step":"cp96-stroke_mm"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"!=":[{"var":"magnet"},"D"]}]},"message_sv":"En givare kräver magnetcylindern CP96SD — välj inbyggd magnet (sida 129).","message_en":"An auto switch needs the CP96SD magnet cylinder — choose the built-in magnet (page 129).","goto_step":"cp96-magnet"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch"},""]},{"or":[{"!=":[{"var":"lead"},""]},{"!=":[{"var":"count"},""]}]}]},"message_sv":"Kabellängd och antal hör till givaren — välj en givare först.","